  ('15', 'bio-custom-mix', 'BIO CUSTOM-MIX', NULL, '39', '/images/default-product.svg', '{/images/default-product.svg}', 'false', 'BTV-011', 'Sản phẩm pha chế theo công thức riêng của trang trại và nhà phân phối.', 'Products formulated to the specific requirements of farms and distributors.', '[{"title": "Thành phần", "content": "Mỗi đơn vị BIO CUSTOM-MIX chứa các hoạt chất chính theo công thức tiêu chuẩn GMP-WHO của BIOTECH-VET. (Thông tin mẫu — cập nhật trong trang quản trị.)"}, {"title": "Công dụng", "content": "Hỗ trợ phòng và điều trị theo chỉ định, nâng cao sức khỏe, sức đề kháng và năng suất cho vật nuôi."}, {"title": "Cách dùng & liều lượng", "content": "Sử dụng theo hướng dẫn của bác sĩ thú y. Pha hoặc trộn theo tỉ lệ khuyến cáo ghi trên bao bì."}, {"title": "Bảo quản", "content": "Nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp. Để xa tầm tay trẻ em."}]', '2026-06-23 19:14:47.727', '2026-06-24 06:19:08.431', '[{"title": "Composition", "content": "Each unit of BIO CUSTOM-MIX contains the main active ingredients per BINOVET''s GMP-WHO standard formula. (Sample content — update in the admin panel.)"}, {"title": "Indications", "content": "Supports prevention and treatment as directed, improving the health, immunity and productivity of livestock."}, {"title": "Dosage & administration", "content": "Use as directed by a veterinarian. Mix or blend at the recommended ratio printed on the packaging."}, {"title": "Storage", "content": "Store in a cool, dry place away from direct sunlight. Keep out of reach of children."}]'),
  ('2', 'bio-tylosin-inj', 'BIO-TYLOSIN INJ', 'BIO-TYLOSIN INJ', '55', '/images/default-product.svg', '{/images/default-product.svg}', 'false', 'BTV-002', 'Dung dịch tiêm điều trị viêm phổi, viêm khớp và các bệnh do Mycoplasma.', 'Injectable solution for pneumonia, arthritis and Mycoplasma-related diseases.', '[{"title": "Thành phần", "content": "Mỗi đơn vị BIO-TYLOSIN INJ chứa các hoạt chất chính theo công thức tiêu chuẩn GMP-WHO của BINOVET. (Thông tin mẫu — cập nhật trong trang quản trị.)"}, {"title": "Công dụng", "content": "Hỗ trợ phòng và điều trị theo chỉ định, nâng cao sức khỏe, sức đề kháng và năng suất cho vật nuôi."}, {"title": "Cách dùng & liều lượng", "content": "Sử dụng theo hướng dẫn của bác sĩ thú y. Pha hoặc trộn theo tỉ lệ khuyến cáo ghi trên bao bì."}, {"title": "Bảo quản", "content": "Nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp. Để xa tầm tay trẻ em."}]', '2026-06-23 18:11:53.851', '2026-07-10 06:20:55.393', '[{"title": "Composition", "content": "Each unit of BIO-TYLOSIN INJ contains the main active ingredients per BINOVET''s GMP-WHO standard formula. (Sample content — update in the admin panel.)"}, {"title": "Indications", "content": "Supports prevention and treatment as directed, improving the health, immunity and productivity of livestock."}, {"title": "Dosage & administration", "content": "Use as directed by a veterinarian. Mix or blend at the recommended ratio printed on the packaging."}, {"title": "Storage", "content": "Store in a cool, dry place away from direct sunlight. Keep out of reach of children."}]'),
  ('13', 'bio-coxistop', 'BIO-COXISTOP', NULL, '56', '/images/default-product.svg', '{/images/default-product.svg}', 'true', 'BTV-009', 'Dung dịch uống đặc trị cầu trùng (Eimeria) trên gà và thỏ, phục hồi nhanh niêm mạc ruột.', 'Oral solution targeting coccidiosis (Eimeria) in chickens and rabbits, restoring intestinal mucosa quickly.', '[{"title": "Thành phần", "content": "Mỗi đơn vị BIO-COXISTOP chứa các hoạt chất chính theo công thức tiêu chuẩn GMP-WHO của BINOVET. (Thông tin mẫu — cập nhật trong trang quản trị.)"}, {"title": "Công dụng", "content": "Hỗ trợ phòng và điều trị theo chỉ định, nâng cao sức khỏe, sức đề kháng và năng suất cho vật nuôi."}, {"title": "Cách dùng & liều lượng", "content": "Sử dụng theo hướng dẫn của bác sĩ thú y. Pha hoặc trộn theo tỉ lệ khuyến cáo ghi trên bao bì."}, {"title": "Bảo quản", "content": "Nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp. Để xa tầm tay trẻ em."}]', '2026-06-23 19:14:47.723', '2026-07-04 05:58:08.603', '[{"title": "Composition", "content": "Each unit of BIO-COXISTOP contains the main active ingredients per BINOVET''s GMP-WHO standard formula. (Sample content — update in the admin panel.)"}, {"title": "Indications", "content": "Supports prevention and treatment as directed, improving the health, immunity and productivity of livestock."}, {"title": "Dosage & administration", "content": "Use as directed by a veterinarian. Mix or blend at the recommended ratio printed on the packaging."}, {"title": "Storage", "content": "Store in a cool, dry place away from direct sunlight. Keep out of reach of children."}]'),
  ('3', 'bio-electrolyte-plus', 'BIO-ELECTROLYTE PLUS', 'BIO-ELECTROLYTE PLUS', '58', '/images/default-product.svg', '{/images/default-product.svg}', 'false', 'BTV-003', 'Bổ sung chất điện giải, vitamin và khoáng chất giúp vật nuôi chống stress nhiệt.', 'Supplies electrolytes, vitamins and minerals to help livestock cope with heat stress.', '[{"title": "Thành phần", "content": "Mỗi đơn vị BIO-ELECTROLYTE PLUS chứa các hoạt chất chính theo công thức tiêu chuẩn GMP-WHO của BINOVET. (Thông tin mẫu — cập nhật trong trang quản trị.)"}, {"title": "Công dụng", "content": "Hỗ trợ phòng và điều trị theo chỉ định, nâng cao sức khỏe, sức đề kháng và năng suất cho vật nuôi."}, {"title": "Cách dùng & liều lượng", "content": "Sử dụng theo hướng dẫn của bác sĩ thú y. Pha hoặc trộn theo tỉ lệ khuyến cáo ghi trên bao bì."}, {"title": "Bảo quản", "content": "Nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp. Để xa tầm tay trẻ em."}]', '2026-06-23 18:11:53.852', '2026-07-10 06:20:45.847', '[{"title": "Composition", "content": "Each unit of BIO-ELECTROLYTE PLUS contains the main active ingredients per BINOVET''s GMP-WHO standard formula. (Sample content — update in the admin panel.)"}, {"title": "Indications", "content": "Supports prevention and treatment as directed, improving the health, immunity and productivity of livestock."}, {"title": "Dosage & administration", "content": "Use as directed by a veterinarian. Mix or blend at the recommended ratio printed on the packaging."}, {"title": "Storage", "content": "Store in a cool, dry place away from direct sunlight. Keep out of reach of children."}]'),
  ('75', 'meloxim', 'MELOXIM', 'MELOXIM', '48', 'https://yyilbcowpzlvsogycici.supabase.co/storage/v1/object/public/uploads/images/1783137092661-meloim.webp', '{}', 'true', 'BTV-114', 'HẠ SỐT NHANH, GIẢM ĐAU, KHÁNG VIÊM MẠNH HỖ TRỢ ĐIỀU TRỊ CÁC BỆNH HÔ HẤP, VIÊM VÚ, NHIỄM TRÙNG HUYẾT, VIÊM CƠ, XƯƠNG, KHỚP, MÓNG', 'RAPID ANTIPYRETIC • POTENT ANALGESIC • STRONG ANTI-INFLAMMATORY ACTION
INSERT INTO "articles" ("id", "slug", "title", "titleEn", "category", "publishDate", "thumbnail", "excerpt", "excerptEn", "content", "contentEn", "featured", "isDraft", "createdAt", "updatedAt") VALUES
  ('4', 'biotechvet-mo-rong-nha-may', 'BIOTECH-VET khánh thành dây chuyền sản xuất mới', 'BIOTECH-VET inaugurates a new production line', 'tin-noi-bo', '01/06/2026', '/images/default-article.svg', 'Đầu tư dây chuyền đạt chuẩn GMP-WHO nâng cao năng lực cung ứng dược thú y.', 'A GMP-WHO compliant line boosts our veterinary pharmaceutical supply capacity.', '<p>Dây chuyền mới ứng dụng công nghệ tự động hóa, nâng công suất gấp đôi và đảm bảo chất lượng đồng đều cho mọi lô sản phẩm.</p>', '<p>The new line applies automation technology, doubling capacity and ensuring consistent quality across every batch.</p>', 'true', 'false', '2026-06-23 18:11:53.869', '2026-06-23 19:41:20.87'),
  ('2', 'benh-cau-trung-tren-ga', 'Bệnh cầu trùng trên gà: nhận biết và điều trị', 'Coccidiosis in chickens: recognition and treatment', 'cam-nang', '01/06/2026', '/images/default-article.svg', 'Hướng dẫn nhận biết sớm và phác đồ điều trị bệnh cầu trùng giúp giảm thiệt hại đàn gà.', 'A guide to early recognition and treatment protocols for coccidiosis to reduce flock losses.', '<p>Bệnh cầu trùng do ký sinh trùng Eimeria gây ra, biểu hiện phân lẫn máu, gà ủ rũ. Sử dụng thuốc đặc trị kết hợp bổ sung vitamin K và điện giải.</p>', '<p>Coccidiosis is caused by Eimeria parasites, presenting as bloody droppings and lethargy. Use targeted anticoccidials combined with vitamin K and electrolyte supplementation.</p>', 'true', 'false', '2026-06-23 18:11:53.864', '2026-07-04 05:58:09.21'),
  ('3', 'ky-thuat-uom-ga-con', 'Kỹ thuật úm gà con đúng cách', 'Proper brooding techniques for chicks', 'cam-nang', '01/06/2026', '/images/default-article.svg', 'Quản lý nhiệt độ, độ ẩm và mật độ chuồng úm để gà con phát triển khỏe mạnh.', 'Managing temperature, humidity and stocking density in the brooder for healthy chicks.', '<p>Giai đoạn úm quyết định sức khỏe cả vòng đời. Tuần đầu duy trì 32-34°C, giảm dần mỗi tuần. Đảm bảo nước sạch và thức ăn chất lượng.</p>', '<p>The brooding stage shapes lifelong health. Keep 32-34°C in the first week, lowering weekly. Ensure clean water and quality feed.</p>', 'true', 'false', '2026-06-23 18:11:53.866', '2026-07-04 05:58:09.26'),
  ('46', 'binovet-mo-rong-nha-may', 'BINOVET khánh thành dây chuyền sản xuất mới', 'BINOVET inaugurates a new production line', 'tin-noi-bo', '01/06/2026', '/images/default-article.svg', 'Đầu tư dây chuyền đạt chuẩn GMP-WHO nâng cao năng lực cung ứng dược thú y.', 'A GMP-WHO compliant line boosts our veterinary pharmaceutical supply capacity.', '<p>Dây chuyền mới ứng dụng công nghệ tự động hóa, nâng công suất gấp đôi và đảm bảo chất lượng đồng đều cho mọi lô sản phẩm.</p>', '<p>The new line applies automation technology, doubling capacity and ensuring consistent quality across every batch.</p>', 'true', 'false', '2026-06-28 06:16:57.594', '2026-07-04 05:58:09.31'),
  ('5', 'thi-truong-chan-nuoi-2026', 'Triển vọng thị trường chăn nuôi năm 2026', 'Outlook for the livestock market in 2026', 'tin-nganh', '01/06/2026', '/images/default-article.svg', 'Phân tích xu hướng giá và nhu cầu thị trường chăn nuôi trong năm tới.', 'An analysis of price trends and market demand in the livestock sector next year.', '<p>Giá heo hơi dự báo phục hồi, nhu cầu protein động vật tăng. Người chăn nuôi nên tối ưu chi phí thức ăn và tăng cường phòng bệnh.</p>', '<p>Live hog prices are expected to recover as demand for animal protein rises. Farmers should optimize feed costs and strengthen disease prevention.</p>', 'true', 'false', '2026-06-23 18:11:53.871', '2026-07-04 05:58:09.359'),
  ('6', 'kiem-soat-doc-to-nam-moc', 'Kiểm soát độc tố nấm mốc trong thức ăn chăn nuôi', 'Controlling mycotoxins in animal feed', 'tin-nganh', '01/06/2026', '/images/default-article.svg', 'Nguy cơ từ độc tố nấm mốc và giải pháp hấp phụ giúp bảo vệ sức khỏe đàn vật nuôi.', 'Risks from mycotoxins and binder solutions that protect herd health.', '<p>Độc tố nấm mốc gây giảm năng suất và suy giảm miễn dịch. Sử dụng chất hấp phụ độc tố và bảo quản nguyên liệu khô ráo là giải pháp then chốt.</p>', '<p>Mycotoxins reduce productivity and impair immunity. Using toxin binders and storing raw materials dry are key solutions.</p>', 'true', 'false', '2026-06-23 18:11:53.872', '2026-07-04 05:58:09.41'),
  ('19', 'ky-thuat-nuoi-heo-nai-sinh-san', 'Kỹ thuật nuôi heo nái sinh sản đạt năng suất cao', 'High-yield sow husbandry techniques', 'cam-nang', '01/06/2026', '/images/default-article.svg', 'Quản lý dinh dưỡng, phối giống và chăm sóc heo nái qua từng giai đoạn để tối ưu số con cai sữa.', 'Managing nutrition, breeding and sow care through each stage to maximise weaned piglets.', '<p>Heo nái cần khẩu phần và chăm sóc khác nhau theo giai đoạn hậu bị, mang thai và nuôi con. Theo dõi thể trạng, bổ sung khoáng – vitamin và đảm bảo chuồng mát giúp tăng số con cai sữa/nái/năm.</p>', '<p>Sows need different diets and care during the gilt, gestation and lactation stages. Monitoring body condition, supplementing minerals and vitamins, and keeping barns cool increases weaned piglets per sow per year.</p>', 'true', 'false', '2026-06-23 19:28:22.365', '2026-07-04 05:58:09.46'),
  ('20', 'ky-thuat-vo-beo-bo-thit', 'Kỹ thuật vỗ béo bò thịt hiệu quả', 'Effective beef cattle fattening techniques', 'cam-nang', '01/06/2026', '/images/default-article.svg', 'Phối hợp khẩu phần tinh – thô và bổ sung vi khoáng giúp bò tăng trọng nhanh, thịt đạt chất lượng.', 'Balancing concentrate and roughage with trace-mineral supplements for fast, quality weight gain.', '<p>Giai đoạn vỗ béo nên tăng dần tỉ lệ thức ăn tinh, bổ sung men tiêu hóa và vi khoáng. Cung cấp đủ nước sạch và tẩy ký sinh trùng định kỳ để bò hấp thu tối đa.</p>', '<p>During fattening, gradually raise the concentrate ratio and add digestive enzymes and trace minerals. Provide clean water and deworm regularly for maximum feed conversion.</p>', 'true', 'false', '2026-06-23 19:28:22.368', '2026-07-04 05:58:09.513'),
  ('22', 'quan-ly-dan-ga-de-trung', 'Quản lý đàn gà đẻ để tối ưu năng suất trứng', 'Managing layer flocks to optimise egg output', 'cam-nang', '01/06/2026', '/images/default-article.svg', 'Kiểm soát ánh sáng, dinh dưỡng canxi và mật độ nuôi để duy trì tỉ lệ đẻ cao và vỏ trứng chắc.', 'Controlling lighting, calcium nutrition and density to sustain high lay rate and strong shells.', '<p>Gà đẻ cần chương trình chiếu sáng ổn định 16 giờ/ngày, khẩu phần giàu canxi và mật độ hợp lý. Bổ sung vitamin D3 và khoáng giúp vỏ trứng chắc, giảm dập vỡ.</p>', '<p>Layers need a stable 16-hour lighting program, a calcium-rich diet and appropriate density. Vitamin D3 and mineral supplements strengthen shells and reduce breakage.</p>', 'true', 'false', '2026-06-23 19:28:22.371', '2026-07-04 05:58:09.615'),
  ('1', 'phong-tri-dich-ta-heo-chau-phi', 'Phòng và kiểm soát dịch tả heo Châu Phi (ASF)', 'Preventing and controlling African Swine Fever (ASF)', 'cam-nang', '01/06/2026', '/images/default-article.svg', 'Các biện pháp an toàn sinh học cốt lõi giúp trang trại phòng chống hiệu quả dịch tả heo Châu Phi.', 'Core biosecurity measures that help farms effectively prevent African Swine Fever.', '<p>Dịch tả heo Châu Phi là bệnh truyền nhiễm nguy hiểm. An toàn sinh học là chìa khóa: kiểm soát người và phương tiện ra vào, sát trùng định kỳ, và cách ly heo mới nhập đàn.</p>', '<p>African Swine Fever is a dangerous infectious disease. Biosecurity is key: control people and vehicle access, disinfect regularly, and quarantine newly introduced pigs.</p>', 'true', 'false', '2026-06-23 18:11:53.862', '2026-07-04 05:58:09.158'),
  ('21', 'phong-benh-tu-huyet-trung-trau-bo', 'Phòng bệnh tụ huyết trùng ở trâu bò', 'Preventing haemorrhagic septicaemia in cattle', 'cam-nang', '01/06/2026', '/images/default-article.svg', 'Nhận biết triệu chứng và lịch tiêm phòng giúp kiểm soát bệnh tụ huyết trùng trên đàn trâu bò.', 'Recognising symptoms and a vaccination schedule to control haemorrhagic septicaemia in herds.', '<p>Bệnh tụ huyết trùng diễn biến nhanh, gây sốt cao và sưng phù vùng hầu. Tiêm vắc-xin định kỳ trước mùa mưa, kết hợp kháng sinh đặc hiệu khi phát hiện sớm là biện pháp hiệu quả.</p>', '<p>Haemorrhagic septicaemia progresses rapidly with high fever and throat swelling. Routine vaccination before the rainy season plus targeted antibiotics at early detection are effective measures.</p>', 'true', 'false', '2026-06-23 19:28:22.369', '2026-07-04 05:58:09.563');
